import{_ as a,o as i,c as o,a2 as s}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"Ética Tecnológica e Limites de Segurança","description":"","frontmatter":{},"headers":[],"relativePath":"pt/68-技术伦理与安全边界.md","filePath":"pt/68-技术伦理与安全边界.md","lastUpdated":1789183869000}'),t={name:"pt/68-技术伦理与安全边界.md"};function r(d,e,n,l,c,m){return i(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="etica-tecnologica-e-limites-de-seguranca" tabindex="-1">Ética Tecnológica e Limites de Segurança <a class="header-anchor" href="#etica-tecnologica-e-limites-de-seguranca" aria-label="Permalink to &quot;Ética Tecnológica e Limites de Segurança&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do Documento</td><td>68</td></tr><tr><td>Módulo</td><td>Sistema de Tecnologia e Energia</td></tr><tr><td>Palavras-chave Principais</td><td>Ética tecnológica, limites de segurança, classificação de risco, tecnologia proibida, revisão ética</td></tr></tbody></table><h2 id="i-principios-fundamentais-da-etica-tecnologica" tabindex="-1">I. Princípios Fundamentais da Ética Tecnológica <a class="header-anchor" href="#i-principios-fundamentais-da-etica-tecnologica" aria-label="Permalink to &quot;I. Princípios Fundamentais da Ética Tecnológica&quot;">​</a></h2><p>A ética tecnológica da civilização de simbiose de âncora é construída sobre o valor fundamental da &quot;evolução simbiótica&quot;. A pesquisa e a aplicação de qualquer tecnologia devem responder a uma pergunta central: esta tecnologia promove a evolução simbiótica de todos os seres, ou fornece novos meios para a pilhagem e o dano? Se a resposta for a última, independentemente de quão grande seja a eficácia individual dessa tecnologia, ela deve ser estritamente limitada ou proibida.</p><p>Os princípios fundamentais da ética tecnológica incluem três:</p><ul><li><strong>Princípio de não causar dano</strong>: A aplicação da tecnologia não deve causar danos desnecessários a nenhum ser vivo, nem fornecer ferramentas para o cultivo predatório</li><li><strong>Princípio de ganho simbiótico</strong>: O desenvolvimento da tecnologia deve ter como objetivo aumentar o grau de simbiose de toda a civilização, em vez de apenas aumentar a capacidade de alguns indivíduos</li><li><strong>Princípio de transparência e rastreabilidade</strong>: O processo de pesquisa e os registros de aplicação de todas as tecnologias de nível de engenharia de leis devem ser rastreáveis, sujeitos a revisão ética e supervisão pública</li></ul><h2 id="ii-sistema-de-classificacao-de-risco-tecnologico" tabindex="-1">II. Sistema de Classificação de Risco Tecnológico <a class="header-anchor" href="#ii-sistema-de-classificacao-de-risco-tecnologico" aria-label="Permalink to &quot;II. Sistema de Classificação de Risco Tecnológico&quot;">​</a></h2><p>A civilização de simbiose estabeleceu um rigoroso sistema de classificação de risco tecnológico, realizando avaliação de risco e gerenciamento classificado para todas as tecnologias de nível de engenharia de leis:</p><table tabindex="0"><thead><tr><th>Nível de Risco</th><th>Nome</th><th>Características</th><th>Requisitos de Gerenciamento</th></tr></thead><tbody><tr><td>R0</td><td>Sem risco</td><td>Tecnologia de nível de ciência e tecnologia real, não envolve manipulação de leis</td><td>Gerenciamento convencional, pesquisa e aplicação livres</td></tr><tr><td>R1</td><td>Baixo risco</td><td>Tecnologia de nível de capacitação por leis, melhoria de desempenho da tecnologia existente</td><td>Gerenciamento de registro, deve passar por testes de segurança básicos</td></tr><tr><td>R2</td><td>Risco médio</td><td>Tecnologia de nível de engenharia de leis, envolve manipulação limitada de leis</td><td>Gerenciamento de licença, deve passar por revisão ética e verificação em espaço isolado</td></tr><tr><td>R3</td><td>Alto risco</td><td>Envolve operações de alto risco como reescrita espacial, intervenção de consciência, fusão de energia, etc.</td><td>Controle rigoroso, apenas instituições autorizadas podem pesquisar em espaço isolado de nível S</td></tr><tr><td>R4</td><td>Nível proibido</td><td>Tecnologias que podem causar colapso de plano, extinção de consciência, poluição de leis</td><td>Proibição total de pesquisa e aplicação, conhecimento relacionado listado como proibido</td></tr></tbody></table><p>O nível de risco não é imutável. Com o amadurecimento da tecnologia e o aprimoramento das medidas de segurança, algumas tecnologias de nível R3 podem ser rebaixadas para o nível R2; por outro lado, se novos riscos de segurança forem descobertos, a tecnologia também pode ser submetida a controle aprimorado.</p><h2 id="iii-limites-de-seguranca-chave" tabindex="-1">III. Limites de Segurança Chave <a class="header-anchor" href="#iii-limites-de-seguranca-chave" aria-label="Permalink to &quot;III. Limites de Segurança Chave&quot;">​</a></h2><p>A ética tecnológica e os limites de segurança delineiam claramente as seguintes linhas vermelhas intransponíveis:</p><h3 id="_3-1-limites-de-seguranca-energetica" tabindex="-1">3.1 Limites de Segurança Energética <a class="header-anchor" href="#_3-1-limites-de-seguranca-energetica" aria-label="Permalink to &quot;3.1 Limites de Segurança Energética&quot;">​</a></h3><ul><li>Proibido realizar experimentos de liberação de energia que excedam a capacidade de suporte do plano no plano principal</li><li>Proibido pesquisar tecnologias de extração de energia com o objetivo de pilhar a energia de outros seres vivos</li><li>A pesquisa de energia estranha deve ser realizada em espaço isolado e seguir rigorosamente os três tipos de processos de disposição</li></ul><h3 id="_3-2-limites-de-seguranca-espacial" tabindex="-1">3.2 Limites de Segurança Espacial <a class="header-anchor" href="#_3-2-limites-de-seguranca-espacial" aria-label="Permalink to &quot;3.2 Limites de Segurança Espacial&quot;">​</a></h3><ul><li>Proibido realizar experimentos de reescrita de leis espaciais em estado não isolado</li><li>A abertura de canais entre planos deve passar por avaliação de segurança para evitar danos permanentes às barreiras entre planos</li><li>A construção e destruição de espaços isolados devem seguir protocolos padrão, não podendo deixar vestígios espaciais</li></ul><h3 id="_3-3-limites-de-seguranca-de-consciencia" tabindex="-1">3.3 Limites de Segurança de Consciência <a class="header-anchor" href="#_3-3-limites-de-seguranca-de-consciencia" aria-label="Permalink to &quot;3.3 Limites de Segurança de Consciência&quot;">​</a></h3><ul><li>Proibido pesquisar tecnologias de manipulação de consciência e alteração de memória sem consentimento</li><li>A pesquisa de corpos de substituição escuros deve seguir os princípios éticos de alma dupla e as quatro regras de disposição de ramificações</li><li>A tecnologia de interface de domínio de consciência deve ter um mecanismo de fusível de segurança irreversível</li></ul><h3 id="_3-4-limites-de-seguranca-temporal" tabindex="-1">3.4 Limites de Segurança Temporal <a class="header-anchor" href="#_3-4-limites-de-seguranca-temporal" aria-label="Permalink to &quot;3.4 Limites de Segurança Temporal&quot;">​</a></h3><ul><li>As operações de retrocesso temporal devem seguir rigorosamente o princípio de &quot;primeiro observar, depois intervir limitadamente&quot;</li><li>Proibido qualquer experimento e operação que possa causar paradoxo temporal</li><li>Os registros de retrocesso temporal devem ser continuamente monitorados pelo mecanismo de prevenção de paradoxo temporal</li></ul><h2 id="iv-mecanismo-de-revisao-etica" tabindex="-1">IV. Mecanismo de Revisão Ética <a class="header-anchor" href="#iv-mecanismo-de-revisao-etica" aria-label="Permalink to &quot;IV. Mecanismo de Revisão Ética&quot;">​</a></h2><p>Para garantir a implementação da ética tecnológica, a civilização de simbiose estabeleceu um mecanismo de revisão ética de vários níveis:</p><ol><li><strong>Revisão antes da pesquisa</strong>: Todos os projetos de pesquisa de tecnologia de nível R2 ou superior devem apresentar um pedido de revisão ética antes do início, e um comitê ético tecnológico independente avaliará seus riscos e benefícios</li><li><strong>Monitoramento durante o experimento</strong>: O processo experimental de tecnologias de nível R3 deve ter observadores éticos presentes o tempo todo, e os dados experimentais devem ser carregados em tempo real para o sistema de monitoramento ético da rede de âncoras</li><li><strong>Avaliação antes da aplicação</strong>: Antes que uma nova tecnologia saia do laboratório para a produção em massa, ela deve passar por avaliação de segurança independente e avaliação de impacto social</li><li><strong>Rastreamento após a aplicação</strong>: As tecnologias já aplicadas continuam recebendo rastreamento de segurança, e quando novos problemas éticos são descobertos, a reavaliação ou até mesmo o programa de recall pode ser iniciado a qualquer momento</li><li><strong>Participação pública</strong>: Decisões tecnológicas importantes devem passar por processos de audiência pública, garantindo que a direção do desenvolvimento tecnológico esteja alinhada com os interesses comuns de toda a civilização</li></ol><h2 id="v-lista-de-tecnologias-proibidas" tabindex="-1">V. Lista de Tecnologias Proibidas <a class="header-anchor" href="#v-lista-de-tecnologias-proibidas" aria-label="Permalink to &quot;V. Lista de Tecnologias Proibidas&quot;">​</a></h2><p>As seguintes tecnologias são explicitamente listadas como tecnologias proibidas de nível R4, com proibição total de pesquisa:</p><ul><li>Armas de nível de destruição de plano: tecnologias de armas capazes de destruir a estrutura espacial de um plano inteiro</li><li>Dispositivos de extinção de consciência: tecnologias capazes de apagar em massa ou escravizar a consciência dos seres vivos</li><li>Motor de leis de pilhagem: tecnologias que usam a pilhagem sistemática da origem de outros seres vivos como mecanismo de operação</li><li>Gerador de paradoxo temporal: tecnologias que criam deliberadamente paradoxos temporais para obter benefícios indevidos</li><li>Disseminador de poluição de leis: tecnologias que espalham deliberadamente a poluição de leis para destruir outras civilizações</li></ul><p>O conhecimento relacionado às tecnologias proibidas é armazenado criptografado nos arquivos proibidos do âncora principal, e só pode ser consultado em crises de segurança de nível civilizacional, após autorização da mais alta autoridade da instituição de governança de simbiose.</p><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>A ética tecnológica e os limites de segurança são o &quot;sistema de freios&quot; do sistema tecnológico da civilização de simbiose de âncora. Ele garante que o desenvolvimento da tecnologia sempre sirva ao objetivo fundamental da evolução simbiótica, sem se alienar em uma nova ferramenta de pilhagem. Em uma época em que as leis podem ser manipuladas por engenharia, os limites éticos são mais importantes do que a capacidade tecnológica — somente mantendo os limites, a tecnologia pode realmente se tornar um auxílio, e não uma ameaça, para o progresso conjunto de todas as raças.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>60-Visão Geral do Sistema Tecnológico</li><li>19-Ética e Limites do Cultivo</li><li>88-Princípios Éticos Entre Planos</li></ul>',31)])])}const g=a(t,[["render",r]]);export{u as __pageData,g as default};
